function STIRLING-TRIANGLE(N):
    S <- (N+1) x (N+1) array of zeros;  S[0][0] <- 1
    for n from 0 to N-1:
        for k from 0 to N-1:
            S[n+1][k+1] <- S[n][k] + (k+1) * S[n][k+1]
    return S

function BELL-NUMBERS(N):
    S <- STIRLING-TRIANGLE(N)
    return [ sum of row S[n] : n = 0..N ]

function CHECK-TOUCHARD(primes, N):
    B <- BELL-NUMBERS(max(primes) + N + 2)
    for p in primes, for n from 0 to N:
        assert B[p+n] mod p = (B[n+1] + B[n]) mod p

function KERNEL-SPECTRUM(arity, holds, bound):
    result <- empty map
    for pattern in ENUMERATE-PATTERNS(arity):
        labels <- sorted distinct entries of pattern
        witness <- none
        for values in [0..bound]^{|labels|}:
            if values are not pairwise distinct: continue
            candidate <- substitute values[label] for each position
            if holds(candidate): witness <- candidate; break
        result[pattern] <- witness
    return result

function EQUAL-LEGS-DIMENSION(k, bound):
    for a from 1 to bound:
        if k * a^2 is a perfect square y^2: return (a, y)
    return none

